import { formatAnnotation } from './jpaFormat.js';
import { capitalize } from './jpaNames.js';
import { Imports, type Attribute, type ModelPlan } from './jpaTypes.js';

/** Turns the plan of a model into the text of its Java file. */

const INDENT: string = '  ';

export interface FileLayout {
  packageName: string;
  /** Write the `// <auto-generated>` comment at the top of every file. */
  header: boolean;
  /** Write Lombok annotations (`@Getter`, `@Setter`, ...) in place of hand-written accessors. */
  lombok?: boolean;
}

/** Assembles a Java file: the header comment, the package, the sorted imports and the body. */
export function renderFile(
  layout: FileLayout,
  imports: Imports,
  body: readonly string[]
): string {
  const lines: string[] = [];
  if (layout.header) {
    lines.push(
      '// <auto-generated>',
      '// Generated by ormbridge. Review the output before use.',
      '// </auto-generated>'
    );
  }
  lines.push(`package ${layout.packageName};`, '');
  const importLines: string[] = imports.lines();
  if (importLines.length > 0) {
    lines.push(...importLines, '');
  }
  lines.push(...body);
  return `${lines.join('\n')}\n`;
}

/** The getter and setter names of an attribute (`isFeatured` of a boolean is `isFeatured()` and `setFeatured`). */
function accessorNames(attribute: Attribute): { get: string; set: string } {
  const name: string = attribute.name;
  if (attribute.isPrimitiveBoolean === true) {
    const prefixed: RegExpMatchArray | null = name.match(/^is([A-Z].*)$/);
    return prefixed === null
      ? { get: `is${capitalize(name)}`, set: `set${capitalize(name)}` }
      : { get: name, set: `set${prefixed[1] ?? ''}` };
  }
  return { get: `get${capitalize(name)}`, set: `set${capitalize(name)}` };
}

export function attributeLines(attribute: Attribute): string[] {
  const lines: string[] = [];
  for (const node of attribute.annotations) {
    lines.push(...formatAnnotation(node, INDENT.length));
  }
  lines.push(
    `${INDENT}private ${attribute.type} ${attribute.name}${attribute.initializer === undefined ? '' : ` = ${attribute.initializer}`};`
  );
  return lines;
}

export function accessorLines(attribute: Attribute): string[] {
  const names = accessorNames(attribute);
  return [
    `${INDENT}public ${attribute.type} ${names.get}() {`,
    `${INDENT}${INDENT}return ${attribute.name};`,
    `${INDENT}}`,
    '',
    `${INDENT}public void ${names.set}(${attribute.type} ${attribute.name}) {`,
    `${INDENT}${INDENT}this.${attribute.name} = ${attribute.name};`,
    `${INDENT}}`,
  ];
}

/** The text of an entity class file. */
export function renderEntity(plan: ModelPlan, layout: FileLayout): string {
  const imports: Imports = new Imports('jakarta');
  imports.merge(plan.imports);
  for (const attribute of plan.attributes) {
    imports.merge(attribute.imports);
  }
  const body: string[] = [];
  for (const node of plan.classAnnotations) {
    body.push(...formatAnnotation(node, 0));
  }
  if (layout.lombok === true) {
    for (const name of ['Getter', 'Setter', 'NoArgsConstructor']) {
      body.push(`@${imports.use(`lombok.${name}`)}`);
    }
  }
  if (plan.serializable === true) {
    imports.use('java.io.Serializable');
  }
  body.push(
    `public class ${plan.className}${plan.serializable === true ? ' implements Serializable' : ''} {`
  );
  if (plan.serializable === true) {
    body.push(`${INDENT}private static final long serialVersionUID = 1L;`, '');
  }
  plan.attributes.forEach((attribute: Attribute, position: number) => {
    if (position > 0) {
      body.push('');
    }
    body.push(...attributeLines(attribute));
  });
  if (layout.lombok !== true) {
    for (const attribute of plan.attributes) {
      body.push('', ...accessorLines(attribute));
    }
  }
  body.push('}');
  return renderFile(layout, imports, body);
}
